UPDATE data_management
SET backup_server = #{backupServer}
WHERE data_id = #{dataId}

UPDATE data_management
SET data_status = 1-data_status
WHERE data_name= #{data_name}

UPDATE data_management
SET data_server = #{dataServer},
    data_node_id = #{dataNodeId}
WHERE data_name = #{dataName}

UPDATE data_management
SET data_count = data_count + 1
WHERE data_name = #{dataName}
